 * 1. 导出标准插件规范：id, version, select, settle, getPrompt, mount；
 * 2. 挂载于 HUD 预留插槽 `data-xsd-slot="map"`；
 * 3. 视觉：南疆大地图底图 + 绝对定位呼吸圆点 (Pin Marker) + 短地点名；
 * 4. 交互：点击圆点派发 SELECT_NODE 意图，由统一调度器执行原生强制发送与 pending 托管；
 * 5. 正文与标签双核验，杜绝否定/旁观，支持漏标降级防死锁。
 */

const {
  EVENT_DEFS,
  PINS,
  OPEN_DATE,
  CLOSE_DATE,
  createInitialState,
  checkActionBlock,
  getAvailableOptions,
  applyAction,
  stampToDate,
} = require("src/plugins/youjigu_map/event_tree.js");

const { resolveActionResult } = require("src/plugins/youjigu_map/evidence.js");
